-- Part 7 (difficulty-uplift pass): online MCQ bank (comp_mcq_questions) hard (difficulty=3) items
-- for inspection_body_supervisor and project_control_specialist. Same root cause and mechanism as
-- mcq_part7_hard_hse_site_supervisor_seed.sql (see that file for the full ceiling-effect writeup):
-- comp_mcq_generate_test()'s fixed 25% hard quota (schema.sql Section 56) silently dilutes toward
-- easier questions when a role's hard pool is thin. inspection_body_supervisor was at 8/42 hard
-- (19.0%) and project_control_specialist at 8/42 hard (19.0%), both well under the bank-wide ~24%
-- hard share. Adds 9 hard items to each role (all on topics that had zero difficulty=3 items yet
-- for that role), bringing each to roughly 33% hard share.
-- Item design: numeric/multi-step items (hydrotest pressure = 1.5x MAOP, 50/50 earned-value rule
-- calculation, AACE Class 5 estimate accuracy range) and scenario/judgment items weighing two
-- plausible actions against a specific clause or standard (inspection-body authority limits vs
-- FIDIC Engineer's Authority, MOC-style change control, QSRA-driven schedule risk response) rather
-- than single-fact recall. Domain grounding: ISO/IEC 17020 (inspection body impartiality/
-- traceability requirements), ASME B31.4/B31.8 (hydrotest pressure), FIDIC-style Engineer's
-- Authority for inspection_body_supervisor; PMBOK (WBS/CBS alignment, baseline change control,
-- integrated change control), AACE International Recommended Practices 18R-97 (estimate
-- classification) and 57R-09 (quantitative schedule risk analysis) for project_control_specialist.
-- Anti-guessability: correct_option rotated 0..3 per row via the same technique as
-- supabase/seed/mcq_questions_seed.sql; no two items share a scenario shape across the two roles
-- or with the hse_specialist/site_supervisor batch. Idempotent via (job_role, md5(stem_fa)) unique
-- index.

insert into comp_mcq_questions (job_role, category, topic, difficulty, stem_fa, options, correct_option, explanation_fa, standard_ref, approval_status, active)
select 'inspection_body_supervisor', x ->> 0, x ->> 1, (x ->> 2)::smallint, x ->> 3,
  (select jsonb_agg(x -> 4 -> ((i - r.k + 4) % 4) order by i) from generate_series(0, 3) i),
  ((n - 1) % 4)::smallint, x ->> 6, x ->> 7, 'APPROVED', true
from jsonb_array_elements($mcq$[
["TECHNICAL", "انضباط مستندسازی و گزارش‌دهی", 3, "طبق الزامات ISO/IEC 17020 برای بی‌طرفی و ردیابی گزارش بازرسی، کدام ویژگی برای یک گزارش بازرسی معتبر ضروری است؟", ["امکان ویرایش گزارش پس از صدور بدون ثبت نسخه یا دلیل تغییر", "ردیابی کامل (Traceability) شامل تاریخ، بازرس مسئول، روش/استاندارد به‌کاررفته و امکان بازبینی مستقل نتیجه", "کافی بودن امضای شفاهی تایید بدون مستند مکتوب", "حذف جزئیات روش آزمون برای ساده‌سازی گزارش"], 1, "گزارش بازرسی معتبر طبق ISO/IEC 17020 باید کاملاً قابل ردیابی و مستند باشد (چه کسی، چه زمانی، با چه روشی) تا امکان بازبینی و دفاع فنی از نتیجه فراهم باشد؛ ویرایش بدون ثبت نسخه یا نبود مستندات این الزام را نقض می‌کند.", "ISO/IEC 17020"],
["TECHNICAL", "ایمنی در نظارت میدانی", 3, "ناظر دستگاه نظارت هنگام بازدید از محوطه‌ای که در آن کار گرم در جریان است، بدون هماهنگی قبلی با HSE پروژه قصد ورود دارد. اقدام صحیح کدام است؟", ["ادامه بازدید بدون توجه به وضعیت پرمیت چون هدف صرفاً فنی است", "هماهنگی با HSE/مسئول پرمیت پیش از ورود و رعایت الزامات ایمنی محل، حتی برای بازدید کوتاه فنی", "ورود سریع و خروج فوری بدون اطلاع کسی", "درخواست توقف کامل کار برای هر بازدید فنی"], 1, "ناظر دستگاه نظارت هم مشمول الزامات ایمنی سایت است؛ ورود بدون هماهنگی با سیستم پرمیت کار، حتی برای بازدید کوتاه، ریسک HSE ایجاد می‌کند.", "رویه ایمنی بازدید میدانی / سیستم پرمیت کار پروژه"],
["JUDGMENT", "مرز اختیارات دستگاه نظارت", 3, "طبق قرارداد، اختیار تایید نهایی تغییرات طراحی صراحتاً برای مهندس مقیم کارفرما (نه دستگاه نظارت) در نظر گرفته شده است. پیمانکار از سرپرست دستگاه نظارت می‌خواهد یک تغییر طراحی جزئی را مستقیماً تایید کند تا کار متوقف نشود. تصمیم درست کدام است؟", ["تایید فوری چون تغییر جزئی به نظر می‌رسد", "امتناع از تایید خارج از حدود اختیار قراردادی و ارجاع فوری موضوع به مرجع ذی‌صلاح (مهندس مقیم کارفرما) طبق مفاد قرارداد", "تایید غیررسمی شفاهی بدون مستندسازی", "نادیده گرفتن درخواست بدون پاسخ‌دهی به پیمانکار"], 1, "دستگاه نظارت فقط در چارچوب اختیارات تفویض‌شده قراردادی عمل می‌کند؛ تایید خارج از این حدود، حتی برای تغییر «جزئی»، دستگاه نظارت را در مسئولیت غیرمجاز قرار می‌دهد و باید به مرجع ذی‌صلاح ارجاع شود.", "شرایط عمومی قرارداد / حدود اختیارات دستگاه نظارت (مشابه FIDIC Engineer's Authority)"],
["TECHNICAL", "هولد پوینت آزمون هیدرواستاتیک", 3, "اگر فشار آزمون هیدرواستاتیک طراحی خط لوله ۱.۵ برابر فشار طراحی (MAOP) تعیین شده و MAOP برابر ۱۰۰ بار باشد، فشار آزمون هیدرواستاتیک چند بار خواهد بود و چرا ثبت آن باید پیش از رهاسازی فشار به‌عنوان هولد پوینت انجام شود؟", ["۱۰۰ بار؛ ثبت فشار اختیاری است", "۱۵۰ بار؛ باید پیش از رهاسازی فشار به‌عنوان هولد پوینت توسط دستگاه نظارت ثبت و تایید شود تا از دست رفتن شواهد آزمون جلوگیری شود", "۵۰ بار؛ ثبت فقط توسط پیمانکار کافی است", "۱۵۰ بار؛ نیازی به حضور دستگاه نظارت در لحظه اوج فشار نیست"], 1, "فشار آزمون هیدرواستاتیک استاندارد ۱.۵ برابر MAOP یعنی ۱۵۰ بار است؛ چون این وضعیت (اوج فشار/مدت نگهداری) پس از رهاسازی فشار غیرقابل بازتولید است، ثبت و تایید حضوری دستگاه نظارت باید پیش از رهاسازی فشار به‌عنوان هولد پوینت انجام شود.", "ASME B31.4/B31.8 (Hydrostatic Test Pressure) / رویه هولد پوینت آزمون هیدرواستاتیک"],
["SCENARIO", "استقلال و بی‌طرفی قضاوت بازرسی", 3, "کارفرمای اصلی به‌طور غیررسمی به سرپرست دستگاه نظارت فشار می‌آورد تا یک مورد عدم انطباق جزئی را برای جلوگیری از تاخیر گزارش نکند. اقدام درست کدام است؟", ["پذیرش درخواست چون کارفرما ذی‌نفع اصلی پروژه است", "حفظ استقلال حرفه‌ای و ثبت/گزارش دقیق عدم انطباق طبق شواهد فنی، صرف‌نظر از فشار غیررسمی هر طرف", "کاهش شدت طبقه‌بندی عدم انطباق برای رضایت کارفرما", "واگذاری تصمیم گزارش‌دهی به پیمانکار"], 1, "بی‌طرفی و استقلال قضاوت فنی دستگاه نظارت رکن اصلی اعتبار آن است؛ گزارش‌دهی باید صرفاً بر مبنای شواهد فنی باشد، نه فشار هر یک از طرفین پروژه، ولو کارفرما.", "ISO/IEC 17020 (Impartiality Requirements)"],
["PROBLEM_SOLVING", "بازبینی گزارش‌های پیشرفت پیمانکار", 3, "گزارش پیشرفت هفتگی پیمانکار طی چند هفته متوالی درصد پیشرفت فیزیکی بالاتر از آنچه در بازدید میدانی دستگاه نظارت مشاهده می‌شود نشان می‌دهد. اولین گام تحلیلی درست دستگاه نظارت کدام است؟", ["پذیرش گزارش پیمانکار بدون مقایسه چون مستندات رسمی است", "مقایسه سیستماتیک روش اندازه‌گیری/وزن‌دهی پیمانکار با روش مصوب پروژه برای شناسایی منشا اختلاف پیش از هر تایید", "رد خودکار همه گزارش‌های آینده پیمانکار بدون بررسی روش", "نادیده گرفتن اختلاف چون معمولاً جزئی است"], 1, "تکرار منظم اختلاف بین گزارش پیمانکار و مشاهده میدانی نشانه یک اختلاف سیستماتیک در روش اندازه‌گیری/وزن‌دهی است که باید ریشه‌یابی شود، نه پذیرش یا رد کورکورانه.", "رویه راستی‌آزمایی گزارش پیشرفت فیزیکی"],
["TECHNICAL", "تطبیق As-built با اجرای واقعی", 3, "هنگام تایید نهایی نقشه As-Built یک بخش از خط لوله، دستگاه نظارت متوجه می‌شود مختصات یک شیر در نقشه As-Built ارائه‌شده توسط پیمانکار با موقعیت واقعی نقشه‌برداری‌شده در سایت حدود دو متر تفاوت دارد. اقدام درست کدام است؟", ["تایید نقشه ارائه‌شده چون تفاوت جزئی به نظر می‌رسد", "رد تایید تا اصلاح نقشه As-Built مطابق مختصات واقعی نقشه‌برداری‌شده، چون As-Built باید بازتاب دقیق وضعیت ساخته‌شده باشد", "اصلاح مستقیم نقشه توسط دستگاه نظارت بدون بازگرداندن به پیمانکار", "نادیده گرفتن تفاوت چون تجهیز عملکرد دارد"], 1, "نقشه As-Built باید دقیقاً وضعیت اجراشده واقعی را منعکس کند، نه نسخه‌ی طراحی یا برآورد؛ هرگونه مغایرت باید پیش از تایید نهایی توسط پیمانکار اصلاح شود.", "رویه تایید نقشه As-Built"],
["TECHNICAL", "کنترل حریم و مجوزهای زمین", 3, "کشف یک تاسیسات زیرزمینی موجود (مثل کابل برق) در مسیر گودبرداری که در نقشه‌های اولیه درج نشده بود، عمدتاً کدام اقدام دستگاه نظارت را الزامی می‌کند؟", ["ادامه‌ی گودبرداری با احتیاط دستی بدون توقف رسمی", "توقف فوری کار در آن نقطه، اطلاع رسمی به کارفرما/مالک تاسیسات، و به‌روزرسانی نقشه‌ها پیش از ادامه", "نادیده گرفتن چون تاسیسات در نقشه اصلی نبوده است", "واگذاری تصمیم کامل به پیمانکار بدون گزارش رسمی"], 1, "برخورد با تاسیسات زیرزمینی ناشناخته باید فوراً متوقف و رسماً به مالک تاسیسات/کارفرما اطلاع داده شود تا از آسیب جدی و ریسک ایمنی جلوگیری شود.", "رویه کنترل حریم و مجوز زمین (Utility Clearance) پروژه"],
["TECHNICAL", "هماهنگی با دفتر فنی (RFI)", 3, "چه زمانی دستگاه نظارت باید یک RFI رسمی به دفتر فنی/طراح ارسال کند به‌جای تصمیم‌گیری مستقل در سایت؟", ["برای هر سوال جزئی روزمره اجرایی بدون اهمیت فنی", "زمانی که ابهام یا تناقض نقشه/مشخصات فنی فراتر از اختیار تفسیر دستگاه نظارت باشد و بر ایمنی/کیفیت سازه اثر داشته باشد", "هیچ‌وقت، چون دستگاه نظارت باید همیشه مستقل تصمیم بگیرد", "فقط در پایان پروژه برای مستندسازی نهایی"], 1, "RFI ابزار رسمی حل ابهامات فنی است که فراتر از حدود تفسیر مجاز دستگاه نظارت باشند، به‌ویژه وقتی ایمنی یا کیفیت سازه در میان است؛ استفاده از آن برای مسائل بی‌اهمیت روزمره یا کنار گذاشتن کامل آن هر دو نادرست است.", "رویه مدیریت RFI (Request for Information)"]
]$mcq$::jsonb) with ordinality t(x, n)
cross join lateral (select ((((n - 1) % 4)::int - (x ->> 5)::int + 4) % 4) as k) r
on conflict (job_role, md5(stem_fa)) do nothing;

insert into comp_mcq_questions (job_role, category, topic, difficulty, stem_fa, options, correct_option, explanation_fa, standard_ref, approval_status, active)
select 'project_control_specialist', x ->> 0, x ->> 1, (x ->> 2)::smallint, x ->> 3,
  (select jsonb_agg(x -> 4 -> ((i - r.k + 4) % 4) order by i) from generate_series(0, 3) i),
  ((n - 1) % 4)::smallint, x ->> 6, x ->> 7, 'APPROVED', true
